-- Lebanon areas: official cadastral list (CAS via OCHA/HDX, Jan 2026) — localities still missing (research 2026-10-17). Deletes only touch Lebanese rows no listing/request uses.
begin;
on conflict (governorate_id,slug) do nothing;
commit;
-- three duplicates left after the merges
delete from areas a using governorates g where a.id in (7508,7253,7444) and g.id=a.governorate_id and g.country_code='LB' and not exists (select 1 from listings l where l.area_id=a.id) and not exists (select 1 from intake_places p where p.area_id=a.id);
